"""Repository checks. Run before every commit / pull request (CI runs it too).

    python tools/check.py          # report problems
    python tools/check.py --fix    # also regenerate generated files

Checks:
  * Lua syntax of every .lua file (needs luac5.4 / luac)
  * universe data loads and validates (duplicate names, bad routes, ...)
  * the extension index matches verse/extensions/*.lua
  * scenarios: header fields, unique scenario numbers, every place they depend on exists,
    no stock factions (Human Navy / Exuari / Ghosts) in campaign content
  * generated files are up to date (director/generated/world.md, docs/verse_map.svg)
  * every missions/jobs/world module file is required by its loader (unloaded files go in attic/)
  * every story arc (missions/<arc>.lua) has a regression test (tests/arcs/<arc>.lua)
  * jobs: every job type has tests/jobs/<type>.lua; job modules address the job's owning ship
    (JOBS.owner/ships/log/hail/rep), and nothing but core touches EE reputation points directly
  * arc flags: every saved-flag literal is declared in an arc's M.flags; flags of another arc
    are listed in M.reads and never written (a typo in a flag name is an error, not a silent no-op)
  * arcs use the shared ARC helpers (missions/_helpers.lua) instead of local copies, and core
    files (core.lua, verse.lua, ...) never reference the missions layer (ARC, MISSIONS)
  * the two skill copies of missions_api.md are identical
  * the director's Python compiles
"""
from __future__ import annotations

import argparse
import py_compile
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import verse_data  # noqa: E402

INDEX = verse_data.EXT_DIR / "index.lua"
ACTIONS_DIR = ROOT / "ee" / "ragtag" / "director" / "actions"
ACTIONS_INDEX = ACTIONS_DIR / "index.lua"
errors: list[str] = []
warnings: list[str] = []


def extension_index_text() -> str:
    lines = ["-- Generated by tools/check.py --fix / tools/install.py. Do not edit.",
             "-- Loads every universe extension in this folder, alphabetically."]
    for p in verse_data.extension_files():
        lines.append(f'require("ragtag/verse/extensions/{p.name}")')
    return "\n".join(lines) + "\n"


def write_extension_index() -> None:
    INDEX.write_text(extension_index_text())


def action_files() -> list:
    if not ACTIONS_DIR.exists():
        return []
    return sorted(p for p in ACTIONS_DIR.glob("*.lua") if p.name != "index.lua")


def action_index_text() -> str:
    lines = ["-- Generated by tools/check.py --fix / tools/install.py. Do not edit.",
             "-- Loads every director action in this folder, alphabetically."]
    for p in action_files():
        lines.append(f'require("ragtag/director/actions/{p.name}")')
    return "\n".join(lines) + "\n"


def write_action_index() -> None:
    ACTIONS_INDEX.write_text(action_index_text())


def check_lua_syntax() -> None:
    luac = shutil.which("luac5.4") or shutil.which("luac54") or shutil.which("luac")
    if not luac:
        warnings.append("luac not found: skipped Lua syntax check")
        return
    for f in sorted(ROOT.rglob("*.lua")):
        if ".git" in f.parts:
            continue
        r = subprocess.run([luac, "-p", str(f)], capture_output=True, text=True)
        if r.returncode != 0:
            errors.append(f"Lua syntax: {r.stderr.strip()}")


# Patterns that mean "this scenario depends on a universe place".
PLACE_PATTERNS = [
    re.compile(r'VERSE\.at\(\s*"([^"]+)"'),
    re.compile(r'RT\.addStationHook\(\s*"([^"]+)"'),
]
REQUIRE_PLACES = re.compile(r'VERSE\.requirePlaces\(\s*\{([^}]*)\}', re.S)
STOCK_FACTIONS = re.compile(r'"(Human Navy|Exuari|Ghosts)"')
# Scenario numbers used by stock EmptyEpsilon (2024+). Reusing one jumbles the scenario list.
STOCK_NUMBERS = {"00", "02", "03", "05", "06", "07", "08", "10", "20", "27", "29", "30", "31", "32", "33", "34", "39",
                 "44", "47", "48", "49", "50", "51", "53", "54", "55", "56", "57", "58", "59", "60", "62", "74", "79",
                 "81", "88", "99"}


def check_scenarios(places: dict) -> None:
    numbers: dict[str, Path] = {}
    for f in sorted((ROOT / "scenarios").rglob("scenario_*.lua")):
        rel = f.relative_to(ROOT)
        text = f.read_text(encoding="utf-8")
        m = re.match(r"scenario_(\d+)_", f.name)
        if not m:
            errors.append(f"{rel}: name must be scenario_NN_name.lua")
        elif not f.parent.name.startswith("_"):
            if m.group(1) in STOCK_NUMBERS:
                errors.append(f"{rel}: scenario number {m.group(1)} is used by a stock EmptyEpsilon scenario (see CONTRIBUTING.md)")
            if m.group(1) in numbers:
                errors.append(f"{rel}: scenario number {m.group(1)} already used by {numbers[m.group(1)]}")
            numbers[m.group(1)] = rel
        for field in ("Name", "Description", "Type"):
            if not re.search(rf"^-- {field}:", text, re.M):
                errors.append(f"{rel}: missing '-- {field}:' header")
        needed = set()
        for pat in PLACE_PATTERNS:
            needed.update(pat.findall(text))
        declared = set()
        for block in REQUIRE_PLACES.findall(text):
            declared.update(re.findall(r'"([^"]+)"', block))
        for name in sorted(needed | declared):
            if name not in places:
                errors.append(f"{rel}: depends on place '{name}', which the universe doesn't define")
        undeclared = needed - declared
        if undeclared and "VERSE.build" in text:
            warnings.append(f"{rel}: uses {sorted(undeclared)} without listing them in VERSE.requirePlaces")
        if "VERSE.build" in text:
            for fac in sorted(set(STOCK_FACTIONS.findall(text))):
                warnings.append(f"{rel}: uses stock faction '{fac}'; campaign content should use the verse factions")


def check_generated(data: dict, fix: bool) -> None:
    import gen_world
    world = gen_world.render(data)
    if not gen_world.OUT.exists() or gen_world.OUT.read_text() != world:
        if fix:
            gen_world.OUT.parent.mkdir(parents=True, exist_ok=True)
            gen_world.OUT.write_text(world)
            print("regenerated", gen_world.OUT.relative_to(ROOT))
        else:
            errors.append("director/generated/world.md is out of date: run python tools/check.py --fix")
    svg = ROOT / "docs" / "verse_map.svg"
    r = subprocess.run([sys.executable, str(ROOT / "tools" / "make_map.py"), "--stdout"], capture_output=True, text=True)
    if r.returncode != 0:
        errors.append(f"make_map failed: {r.stderr.strip()[-300:]}")
    elif not svg.exists() or svg.read_text() != r.stdout:
        if fix:
            svg.write_text(r.stdout)
            print("regenerated docs/verse_map.svg")
        else:
            errors.append("docs/verse_map.svg is out of date: run python tools/check.py --fix")


# Module directories whose files must be required by their loader. A file that
# exists but isn't required silently never loads (no error in-game), which is
# the #1 way a new mission/job/plugin "doesn't work". Intentionally parked
# files go in a subdirectory (e.g. missions/attic/), which this check ignores.
LOADERS = {
    "ee/ragtag/missions.lua": "ee/ragtag/missions",
    "ee/ragtag/jobs.lua":     "ee/ragtag/jobs",
    "ee/ragtag/world.lua":    "ee/ragtag/world",
}


def check_loader_requires() -> None:
    for loader_rel, dir_rel in LOADERS.items():
        loader = ROOT / loader_rel
        mod_dir = ROOT / dir_rel
        if not loader.exists() or not mod_dir.is_dir():
            continue
        text = loader.read_text(encoding="utf-8")
        for f in sorted(mod_dir.glob("*.lua")):
            if f.name.startswith("_"):
                continue
            needle = f'require("ragtag/{mod_dir.name}/{f.name}")'
            if needle not in text:
                errors.append(
                    f"{dir_rel}/{f.name} is not required by {loader_rel} and will never load "
                    f"(add the require, or park it in {dir_rel}/attic/)")


# missions_api.md is deliberately kept in two skills; they must stay identical.
API_MD_COPIES = [
    ROOT / ".claude" / "skills" / "sandbox-missions" / "references" / "missions_api.md",
    ROOT / ".claude" / "skills" / "empty-epsilon-scenarios" / "references" / "missions_api.md",
]


# Job modules work for whichever ship owns the job, never "all player ships".
JOB_OWNER_RULES = [
    (re.compile(r'RT\.players\b'), "JOBS.ships(m) / JOBS.owner(m) (a job reacts to its owning ship only)"),
    (re.compile(r'RT\.forEachPlayer\('), "JOBS.owner(m)"),
    (re.compile(r'RT\.shipLog\('), "JOBS.log(m, text, color) (job news goes to the owning ship)"),
    (re.compile(r'RT\.hail\('), "JOBS.hail(m, from, text)"),
    (re.compile(r'RT\.addReputation\('), "JOBS.rep(m, faction, amount, reason) (standing is per ship)"),
]
# EmptyEpsilon keeps reputation points per faction, so the raw calls move every player ship's money.
RAW_CREDITS = re.compile(r'[:.](get|set|add|take)ReputationPoints\(')


def check_jobs() -> None:
    """Every job type has a test; job modules address the owning ship; credits go through RT."""
    jobs = ROOT / "ee" / "ragtag" / "jobs"
    tests = ROOT / "tests" / "jobs"
    for f in sorted(jobs.glob("*.lua")):
        if f.name.startswith("_"):
            continue
        rel = f"ee/ragtag/jobs/{f.name}"
        if not (tests / f.name).exists():
            errors.append(f"{rel} has no regression test: add tests/jobs/{f.name} "
                          f"(see tests/_harness.lua; run with tools/game_tests.py)")
        code = _strip_lua_comments(f.read_text(encoding="utf-8"))
        for pat, use in JOB_OWNER_RULES:
            m = pat.search(code)
            if m:
                errors.append(f"{rel}:{code.count(chr(10), 0, m.start()) + 1}: use {use} instead of `{m.group(0)}`")
    for f in sorted((ROOT / "ee" / "ragtag").rglob("*.lua")) + sorted((ROOT / "scenarios").rglob("*.lua")):
        if f.name == "core.lua" and f.parent.name == "ragtag":
            continue
        code = _strip_lua_comments(f.read_text(encoding="utf-8"))
        m = RAW_CREDITS.search(code)
        if m:
            errors.append(f"{f.relative_to(ROOT)}:{code.count(chr(10), 0, m.start()) + 1}: use RT.credits(ship) / "
                          f"RT.addCredits(amount, reason, ship): EmptyEpsilon's reputation points are shared by "
                          f"every ship of a faction, so `{m.group(0)[1:]}...)` changes all player ships' money")


def check_arc_tests() -> None:
    """Every story arc needs tests/arcs/<arc>.lua (run by tools/game_tests.py)."""
    arcs = ROOT / "ee" / "ragtag" / "missions"
    tests = ROOT / "tests" / "arcs"
    for f in sorted(arcs.glob("*.lua")):
        if f.name.startswith("_"):
            continue
        if not (tests / f.name).exists():
            errors.append(f"ee/ragtag/missions/{f.name} has no regression test: add tests/arcs/{f.name} "
                          f"(see tests/_harness.lua; run with tools/game_tests.py)")
    for f in sorted(tests.glob("*.lua")):
        if not f.name.startswith("_") and not (arcs / f.name).exists():
            errors.append(f"tests/arcs/{f.name} tests an arc that does not exist (ee/ragtag/missions/{f.name})")


# Local re-implementations of ARC helpers (ee/ragtag/missions/_helpers.lua) in an arc module.
ARC_DUPLICATES = [
    (re.compile(r'local function _(firstPlayer|player)\b'), "ARC.player()"),
    (re.compile(r'local function _(dist|d2)\b'), "ARC.dist(x1, y1, x2, y2)"),
    (re.compile(r'local function _near\b'), "ARC.near(ent, x, y, r)"),
    (re.compile(r'local function _alive\b'), "ARC.alive(list)"),
    (re.compile(r'local function _kill\b'), "ARC.kill(entity_or_table)"),
    (re.compile(r'local function _addRecords\b'), "ARC.meet(arc_id, profile_key, who)"),
    (re.compile(r'RT\.addStationHook\('), "ARC.stationHook(callsign, fn)"),
    (re.compile(r'MISSIONS\.gmJump\('), "ARC.jumper(arc_id)"),
    (re.compile(r'pairs\(M\.init_state\(\)\)'), "ARC.resetState(M, st)"),
    # Arcs belong to the primary ship only; these address every player ship.
    (re.compile(r'RT\.players\b'), "ARC.player() (arcs act on the arc ship only)"),
    (re.compile(r'RT\.forEachPlayer\('), "ARC.withPlayer(fn) (arcs act on the arc ship only)"),
    (re.compile(r'RT\.shipLog\('), "ARC.log(msg, color) (arc logs go to the arc ship only)"),
    (re.compile(r'RT\.hail\('), "ARC.hail(from, text, speaker) (arc hails go to the arc ship only)"),
    (re.compile(r'RT\.voice\.(hail|log)\('), "ARC.hail(RT.voice.get(id), text, name) / ARC.log (arc ship only)"),
]
# Mission-layer names that must not appear in the layers below it.
CORE_FILES = ["core.lua", "verse.lua", "voice.lua", "stats.lua", "ship_templates.lua"]


def check_arc_helpers() -> None:
    """Arcs use the shared ARC helpers; core does not reach up into the missions layer."""
    arcs = ROOT / "ee" / "ragtag" / "missions"
    for f in sorted(arcs.glob("*.lua")):
        if f.name.startswith("_"):
            continue
        text = f.read_text(encoding="utf-8")
        for pat, use in ARC_DUPLICATES:
            m = pat.search(text)
            if m:
                line = text.count("\n", 0, m.start()) + 1
                errors.append(f"ee/ragtag/missions/{f.name}:{line}: use {use} from missions/_helpers.lua "
                              f"instead of `{m.group(0)}`")
    core = [ROOT / "ee" / "ragtag" / name for name in CORE_FILES] + sorted((ROOT / "ee" / "ragtag" / "core").glob("*.lua"))
    for f in core:
        if not f.exists():
            continue
        name = str(f.relative_to(ROOT / "ee" / "ragtag"))
        code = "\n".join(line.split("--", 1)[0] for line in f.read_text(encoding="utf-8").splitlines())
        for m in re.finditer(r'\b(ARC|MISSIONS)\.', code):
            line = code.count("\n", 0, m.start()) + 1
            errors.append(f"ee/ragtag/{name}:{line}: core code must not use {m.group(1)} "
                          f"(the missions layer sits above core; move the code into ee/ragtag/missions/)")
            break


# ── Arc flags ────────────────────────────────────────────────────────────────
# Saved flags are plain strings shared between arcs, so a typo fails silently in play. Each arc
# declares the flags it owns (M.flags) and the other arcs' flags it reads (M.reads); every flag
# literal in the code is checked against those declarations.
FLAG_KEY = re.compile(r'^\s*(?:([a-z0-9_]+)|\["([a-z0-9_*]+)"\])\s*=\s*[\'"]', re.M)
FLAG_CALL = re.compile(r'(RT\.flag|RT\.clearFlag|ARC\.once|T\.flag)\(\s*"([a-z0-9_]+)"\s*(\.\.)?\s*(,)?')
FLAG_LIST = re.compile(r'\b(?:not_)?flagged\s*=\s*\{([^}]*)\}')
FLAG_ROUTE = re.compile(r'ARC\.route\((.*?)\n\s*\}\s*,\s*"[a-z0-9_]+"\s*\)', re.S)
FLAG_ROUTE_RULE = re.compile(r'\{\s*"([a-z0-9_]+)"\s*,\s*"[a-z0-9_]+"\s*\}')
FLAG_KEEP = re.compile(r'\bname\s*==\s*"([a-z0-9_]+)"')


def _strip_lua_comments(text: str) -> str:
    return "\n".join(line.split("--", 1)[0] for line in text.splitlines())


def _lua_table_body(text: str, start: str) -> str | None:
    """Body of `start = { ... }` (balanced braces), or None."""
    m = re.search(re.escape(start) + r'\s*=\s*\{', text)
    if not m:
        return None
    depth, i = 1, m.end()
    while i < len(text) and depth:
        depth += {"{": 1, "}": -1}.get(text[i], 0)
        i += 1
    return text[m.end():i - 1]


def _flag_uses(code: str) -> list[tuple[str, bool, bool, int]]:
    """(name, is_family_prefix, is_write, line) for every flag literal in Lua code."""
    out = []
    def line_of(pos): return code.count("\n", 0, pos) + 1
    for m in FLAG_CALL.finditer(code):
        fn, name, concat, comma = m.groups()
        write = fn in ("RT.clearFlag", "ARC.once") or (fn == "RT.flag" and bool(comma) and not concat)
        out.append((name, bool(concat), write, line_of(m.start())))
    for m in FLAG_LIST.finditer(code):
        for name in re.findall(r'"([a-z0-9_]+)"', m.group(1)):
            out.append((name, False, False, line_of(m.start())))
    for m in FLAG_ROUTE.finditer(code):
        for r in FLAG_ROUTE_RULE.finditer(m.group(1)):
            out.append((r.group(1), False, False, line_of(m.start(1) + r.start())))
    for m in FLAG_KEEP.finditer(code):
        out.append((m.group(1), False, False, line_of(m.start())))
    return out


def check_arc_flags() -> None:
    arcs_dir = ROOT / "ee" / "ragtag" / "missions"
    arcs = {}   # id -> {file, flags, reads, prefixes, code}
    for f in sorted(arcs_dir.glob("*.lua")):
        if f.name.startswith("_"):
            continue
        rel = f"ee/ragtag/missions/{f.name}"
        code = _strip_lua_comments(f.read_text(encoding="utf-8"))
        body = _lua_table_body(code, "M.flags")
        if body is None:
            errors.append(f"{rel}: no M.flags table: declare every saved flag the arc sets "
                          f"(name = \"meaning\"); see missions_api.md, \"Flags\"")
            continue
        flags = [a or b for a, b in FLAG_KEY.findall(body)]
        reads = re.findall(r'"([a-z0-9_]+)"', _lua_table_body(code, "M.reads") or "")
        pre = re.findall(r'"([a-z0-9_]+)"', _lua_table_body(code, "M.gm_flag_prefixes") or "") or [f.stem + "_"]
        arcs[f.stem] = {"rel": rel, "flags": flags, "reads": reads, "prefixes": pre, "code": code}

    def declared_by(name: str, family: bool = False) -> str | None:
        for aid, a in arcs.items():
            for key in a["flags"]:
                if key == name and not family:
                    return aid
                if key.endswith("*") and name.startswith(key[:-1]) and (not family or name == key[:-1]):
                    return aid
        return None

    def namespace(name: str) -> str | None:
        for aid, a in arcs.items():
            if any(name.startswith(p) for p in a["prefixes"]):
                return aid
        return None

    for aid, a in arcs.items():
        rel = a["rel"]
        for key in a["flags"]:
            if not any(key.startswith(p) for p in a["prefixes"]):
                errors.append(f"{rel}: flag '{key}' does not start with one of the arc's gm_flag_prefixes "
                              f"({', '.join(a['prefixes'])}), so a GM reset would not clear it")
        uses = _flag_uses(a["code"])
        used = {name for name, *_ in uses}
        for name, family, write, line in uses:
            owner = declared_by(name, family)
            shown = name + ("*" if family else "")
            if owner is None:
                errors.append(f"{rel}:{line}: flag '{shown}' is not declared in any arc's M.flags "
                              f"(typo, or add it to M.flags with its meaning)")
            elif owner != aid:
                if name not in a["reads"]:
                    errors.append(f"{rel}:{line}: flag '{shown}' belongs to the {owner} arc: list it in M.reads")
                if write:
                    errors.append(f"{rel}:{line}: flag '{shown}' belongs to the {owner} arc: only its owner sets or clears it")
        for key in a["flags"]:
            if not key.endswith("*") and key not in used:
                errors.append(f"{rel}: flag '{key}' is declared in M.flags but never used in the arc")
        for name in a["reads"]:
            owner = declared_by(name)
            if owner is None or owner == aid:
                errors.append(f"{rel}: M.reads lists '{name}', which no other arc declares")
            elif name not in used:
                errors.append(f"{rel}: M.reads lists '{name}' but the arc never reads it")

    # Arc flags used outside the arcs (other layers, scenarios, arc tests) must exist too.
    others = [f for f in sorted((ROOT / "ee" / "ragtag").rglob("*.lua")) if arcs_dir not in f.parents]
    others += sorted((ROOT / "scenarios").rglob("*.lua")) + sorted((ROOT / "tests").rglob("*.lua"))
    for f in others:
        code = _strip_lua_comments(f.read_text(encoding="utf-8"))
        for name, family, _write, line in _flag_uses(code):
            if namespace(name) and declared_by(name, family) is None:
                errors.append(f"{f.relative_to(ROOT)}:{line}: flag '{name}{'*' if family else ''}' looks like a "
                              f"{namespace(name)} arc flag but is not declared in its M.flags")


def check_api_md_sync() -> None:
    a, b = API_MD_COPIES
    if a.exists() and b.exists() and a.read_text() != b.read_text():
        errors.append("missions_api.md copies differ: sync "
                      f"{a.relative_to(ROOT)} and {b.relative_to(ROOT)}")


def check_python() -> None:
    for f in sorted((ROOT / "director").glob("*.py")) + sorted((ROOT / "tools").glob("*.py")):
        try:
            py_compile.compile(str(f), doraise=True)
        except py_compile.PyCompileError as e:
            errors.append(f"Python: {e.msg}")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--fix", action="store_true", help="regenerate generated files")
    args = ap.parse_args()

    check_lua_syntax()
    current = INDEX.read_text() if INDEX.exists() else ""
    if current != extension_index_text():
        if args.fix:
            write_extension_index()
            print("regenerated", INDEX.relative_to(ROOT))
        else:
            errors.append("verse/extensions/index.lua is out of date: run python tools/check.py --fix")
    current_ai = ACTIONS_INDEX.read_text() if ACTIONS_INDEX.exists() else ""
    if current_ai != action_index_text():
        if args.fix:
            write_action_index()
            print("regenerated", ACTIONS_INDEX.relative_to(ROOT))
        else:
            errors.append("director/actions/index.lua is out of date: run python tools/check.py --fix")
    data = verse_data.load()
    for p in data["problems"]:
        errors.append(f"universe: {p}")
    check_scenarios(data["places"] or {})
    check_generated(data, args.fix)
    check_loader_requires()
    check_arc_tests()
    check_jobs()
    check_arc_helpers()
    check_arc_flags()
    check_api_md_sync()
    check_python()

    for w in warnings:
        print("warning:", w)
    for e in errors:
        print("ERROR:", e)
    print(f"{len(errors)} error(s), {len(warnings)} warning(s). Universe: "
          f"{len(data['stations'])} stations, {len(data['regions'])} regions, extensions: "
          f"{', '.join(e['id'] for e in data['extensions'])}")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
